package rw.schoolpass.web;
import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import rw.schoolpass.repo.*; import rw.schoolpass.model.Student; import rw.schoolpass.service.AuditService; import java.util.*;
@Controller @RequestMapping("/finance") public class FinanceController {private final StudentRepository students;private final AuditService audit;public FinanceController(StudentRepository s,AuditService a){students=s;audit=a;}
 @GetMapping String page(@RequestParam(required=false)String q,Model m){List<Student> list=q==null||q.isBlank()?students.findAll():students.findByFirstNameContainingIgnoreCaseOrLastNameContainingIgnoreCaseOrStudentCodeContainingIgnoreCase(q,q,q);m.addAttribute("students",list);m.addAttribute("query",q==null?"":q);return "finance";}
 @PostMapping("/update/{id}") String update(@PathVariable Long id,@RequestParam long required,@RequestParam long paid,@RequestParam String uniformStatus,Authentication auth){if(required<0||paid<0||paid>required)throw new IllegalArgumentException("Invalid fee values.");Student s=students.findById(id).orElseThrow();s.setFeeRequired(required);s.setFeePaid(paid);s.setFeeStatus(paid>=required&&required>0?"FULLY PAID":paid>0?"PARTIALLY PAID":"UNPAID");s.setUniformStatus(uniformStatus);s.touch();students.save(s);audit.log(auth.getName(),"FINANCE_UPDATED","STUDENT",String.valueOf(id),"Fee/uniform status updated");return "redirect:/finance?success=updated";}
}
